import '@tanstack/react-router'

declare module '@tanstack/react-router' {
  interface StaticDataRouteOption {
    /**
     * 页面标题：由全局 `Header` 渲染成该页唯一的 `h1`。
     *
     * 放在路由上而不是各页面自己写，是为了让「顶部只有一处标题」成为结构约束：
     * 页面组件里不再出现标题横幅，也就不会再出现同一名字写两遍（历史上竞品分析
     * 的页面名同时出现在 Header 和内容区 h1 里）。
     *
     * 带模块内二级导航的模块（AI 助手、AI 治理）只在**模块级路由**上声明模块名，
     * 子页由导航高亮表达位置，避免标题与导航项重复。
     */
    title?: string

    /**
     * 宽屏页：声明后内容区铺满可用宽度，不再受 `Main` 的 `max-w-[1280px]` 居中约束。
     *
     * 默认不铺满是刻意的（1680 视口下正文铺到 1392px 会失去排版边界感），
     * 但**工作台类页面**（多栏同时开工，栏宽被固定栏吃掉后主区只剩一半）是例外：
     * AI 助手对话页左栏 256px + 右栏 320px 后，中栏消息区一度只剩约 550px。
     * 例外必须逐页声明，避免又回到"所有页面一起铺满"。
     *
     * 查找规则与 `title` 相反：`title` 由深往浅取第一个**有值**的标题（子页继承模块名），
     * 而这里取第一个**显式声明**的布尔值，所以子页可以用 `wide: false` 明确关掉继承来的宽度策略。
     */
    wide?: boolean
  }
}
